import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百六十八章 对五位出家人说法","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/268第二百六十八章 对五位出家人说法-非我-非我所.md","filePath":"meditation/巴利文大藏经/268第二百六十八章 对五位出家人说法-非我-非我所.md"}'),o={name:"meditation/巴利文大藏经/268第二百六十八章 对五位出家人说法-非我-非我所.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百六十八章-对五位出家人说法" tabindex="-1">第二百六十八章 对五位出家人说法 <a class="header-anchor" href="#第二百六十八章-对五位出家人说法" aria-label="Permalink to &quot;第二百六十八章 对五位出家人说法&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应59经/无我相经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在波罗奈的鹿野苑，佛陀对五位前来求法的比丘（出家人）说到：“比丘们！没有永远存在的我，没有永远存在的物质身体、物质事物。比丘们！如果我永远存在，那么物质身体就应该不生病、不衰老、不死亡，物质事物就应该能够永远的拥有。如果我永远存在，那么我就能够随意的让物质身体、物质事物这样，让物质身体、物质事物不那样，比如我就能够让物质身体永远健康，永远年轻，生命长存，我就能够永远的拥有物质事物。我就能够让物质身体不生病、不衰老、不死亡，我就能够让物质事物不衰败、不灭亡、不消失。</p><p>但是比丘们！就是因为我无法永远的存在，我无法永远的拥有物质事物，所以我的物质身体会生病、衰老、死亡。我会失去自己所拥有的物质事物，我拥有的物质事物会衰败、灭亡、消失。我不能随意的让物质身体、物质事物这样，我不能随意的让物质身体、物质事物不那样。比如我不能让物质身体永远健康，永远年轻，生命长存，我不能够永远的拥有物质事物。我不能让物质身体不生病、不衰老、不死亡，我不能让物质事物不衰败、不灭亡、不消失。”</p><p>比丘们！没有永远存在的我，没有永远存在的感受、念想、行为、认识、分别、判断。比丘们！如果我永远存在，感受、念想、行为、认识、分别、判断永远存在，那么感受、念想、行为、认识、分别、判断就不应该让人产生烦恼和痛苦，就不应该消退、灭尽、消失。如果我永远存在，那么我就能够随意的让感受、念想、行为、认识、分别、判断这样，让感受、念想、行为、认识、分别、判断不那样，比如我就能够让感受、念想、行为、认识、分别、判断永远令自己满意、开心、快乐。我就能够让满意、开心、快乐的感受、念想、行为、认识、分别、判断不消退、不灭尽、不消失，我就能够让感受、念想、行为、认识、分别、判断不产生烦恼和痛苦。</p><p>但是比丘们！就是因为我无法永远的存在，感受、念想、行为、认识、分别、判断无法永远的存在，所以感受、念想、行为、认识、分别、判断就会让人产生烦恼和痛苦，就会消退、灭尽、消失。我不能随意的让感受、念想、行为、认识、分别、判断这样，我不能让感受、念想、行为、认识、分别、判断不那样，比如我不能让感受、念想、行为、认识、分别、判断永远令自己满意、开心、快乐。我不能让满意、开心、快乐的感受、念想、行为、认识、分别、判断不消退、不灭尽、不消失，我不能让感受、念想、行为、认识、分别、判断不产生烦恼和痛苦。</p><p>比丘们！你们是怎么想的？物质事物、物质身体是永远存在，永恒保持不变，是能够永远拥有的，还是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的？”</p><p>这五位出家人回答：“世尊，物质事物、物质身体随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的，物质事物是会衰败、灭亡、消失的，物质身体是会生病、衰老、死亡的。”</p><p>佛陀说：“比丘们！既然物质事物、物质身体随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的，那么是最终带来痛苦的，还是最终带来快乐的呢？”</p><p>这五位出家人回答：“世尊，物质事物、物质身体最终带来的是痛苦，为什么这么说呢？因为就算物质事物、物质身体带来了快乐，那都是短暂的。世间一切的物质事物、物质身体随时都在变化，无法永远的存在，无法永恒的保持不变，无法永远的拥有，当失去这些物质事物的时候，当这些物质事物衰败、灭亡、消失的时候，当物质身体生病、衰老、临死的时候，就会带来痛苦，之前这些物质事物、物质身体带来了多少的快乐，当失去这些物质事物的时候，当这些物质事物衰败、灭亡、消失的时候，当物质身体生病、衰老、临死的时候，就会带来多少痛苦，所以世间的物质事物、物质身体带来的最终都是痛苦。”</p><p>佛陀说：“比丘们！世间的物质事物、物质身体是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的，是最终带来痛苦的。那么你们会认为：「物质事物是我所拥有的，我就是这个物质身体，这个物质身体就是真实不变、永远存在的我。」吗？简单的说就是，你们会认为：「这是我的，我是这个，这是真实不变、永远存在的我。」吗？”</p><p>这五位出家人回答：“世尊，我们不会这样认为，我不会有这样的见解。”</p><p>佛陀说：“比丘们！你们是怎么想的？感受、念想、行为、认识、分别、判断是永远存在，永恒保持不变，是能够永远拥有的，还是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的？”</p><p>这五位出家人回答：“世尊，感受、念想、行为、认识、分别、判断是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的，感受、念想、行为、认识、分别、判断是会消退、灭尽、消失的。”</p><p>佛陀说：“比丘们！既然感受、念想、行为、认识、分别、判断是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的，那么是最终带来痛苦的，还是最终带来快乐的呢？”</p><p>这五位出家人回答：“世尊，感受、念想、行为、认识、分别、判断最终带来的是痛苦，为什么这么说呢？因为就算感受、念想、行为、认识、分别、判断带来了快乐，那都是短暂的。世间一切的感受、念想、行为、认识、分别、判断随时都在变化，无法永远的存在，无法永恒的保持不变，无法永远的拥有，当失去这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断的时候，当这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断消退、灭尽、消失的时候，当感受、念想、行为、认识、分别、判断让世间人、众生不满意、不开心、不快乐的时候，就会带来痛苦，之前这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断带来了多少的快乐，当失去这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断的时候，当这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断消退、灭尽、消失的时候，当感受、念想、行为、认识、分别、判断让世间人、众生不满意、不开心、不快乐的时候，就会带来多少痛苦，所以世间的感受、念想、行为、认识、分别、判断带来的最终都是痛苦。”</p><p>佛陀说：“比丘们！世间的感受、念想、行为、认识、分别、判断是随时在变化，无法永远存在，无法永恒保持不变，无法永远拥有的，是最终带来痛苦的。那么你们会认为：「感受、念想、行为、认识、分别、判断是我所拥有的，我就是这个感受、念想、行为、认识、分别、判断，这个感受、念想、行为、认识、分别、判断就是真实不变、永远存在的我。」吗？简单的说就是，你们会认为：「这是我的，我是这个，这是真实不变、永远存在的我。」吗？”</p><p>这五位出家人回答：“世尊，我们不会这样认为，我们不会有这样的见解。”</p><p>佛陀说：“比丘们！对于物质事物、物质身体、感受、念想、行为、认识、分别、判断，不论是过去、现在、未来，或者内部，或者外部；或者粗糙，或者细滑；或者低劣，或者优质；或者遥远，或者邻近等等世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断都应该用正确的智慧，这样来看待：「物质事物、物质身体、感受、念想、行为、认识、分别、判断不是我所拥有的，我不是这个物质事物、物质身体、感受、念想、行为、认识、分别、判断，这个物质事物、物质身体、感受、念想、行为、认识、分别、判断不是真实不变、永远存在的我。」简单的说就是：「这不是我的，我不是这个，这不是真实不变、永远存在的我。」</p><p>比丘们！当你们有了这个正确的见解，那就是已经受到了如来的教导。已经受到如来教导的圣弟子们，他们不会执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，当他们不执着和挂念这些事物的时候，就不会被这些事物束缚捆绑，就不会因为这些事物胡思乱想、胡作非为，就不会让这些事物污染自己内心清净的境界。当他们彻底从这些事物中解脱出来的时候，彻底的灭尽一切烦恼和痛苦的时候，他们就开启了解脱的智慧，他们就证悟了解脱的果位，他们自己就明白了：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生在世间了，已经彻底从生死轮回中解脱出来。」”</p><p>佛陀说法后，这五位比丘再次的顶礼佛陀，他们随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行，没有过多久，这五位比丘就不再执着和挂念世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断了，他们就从一切的烦恼和痛苦中解脱出来，证悟了解脱的果位。</p>',22)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
